-- Additive register. No existing tasks, users, activity or inventory rows are modified.
BEGIN;
CREATE TABLE public.board_availability_assets (
 id text PRIMARY KEY,
 property text NOT NULL CHECK(property IN ('Allen','Central','Potts Point','Olympic')),
 kind text NOT NULL CHECK(kind IN ('room','bathroom')),
 label text NOT NULL CHECK(char_length(label) BETWEEN 1 AND 160),
 floor text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', note text NOT NULL DEFAULT '',
 source text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true,
 created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(property,kind,label)
);
CREATE TABLE public.board_availability_reports (
 id text PRIMARY KEY,
 asset_id text NOT NULL REFERENCES public.board_availability_assets(id),
 state text NOT NULL CHECK(state IN ('blocked','available','update')),
 closed_on date,
 reason text NOT NULL DEFAULT '' CHECK(char_length(reason)<=1000),
 action text NOT NULL DEFAULT '' CHECK(char_length(action)<=1000),
 owner text NOT NULL DEFAULT '' CHECK(char_length(owner)<=1000),
 eta text NOT NULL DEFAULT '' CHECK(char_length(eta)<=1000),
 reported_at timestamptz NOT NULL DEFAULT now(),
 actor text NOT NULL CHECK(char_length(actor) BETWEEN 1 AND 100),
 source text NOT NULL CHECK(source IN ('whatsapp','dashboard')),
 source_id text NOT NULL,
 received_at timestamptz NOT NULL DEFAULT now(),
 CHECK(closed_on IS NULL OR closed_on <= (reported_at AT TIME ZONE 'Australia/Sydney')::date),
 UNIQUE(source,source_id,asset_id)
);
CREATE INDEX availability_reports_asset_time ON public.board_availability_reports(asset_id,reported_at,id);
ALTER TABLE public.board_availability_assets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.board_availability_reports ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.board_availability_assets,public.board_availability_reports FROM PUBLIC,anon,authenticated;
-- Preserve this workspace's explicit shared-name mode. No account permissions are expanded.
GRANT SELECT ON public.board_availability_assets,public.board_availability_reports TO anon;
GRANT INSERT ON public.board_availability_reports TO anon;
CREATE POLICY availability_assets_shared_read ON public.board_availability_assets FOR SELECT TO anon USING(true);
CREATE POLICY availability_reports_shared_read ON public.board_availability_reports FOR SELECT TO anon USING(true);
CREATE POLICY availability_reports_append ON public.board_availability_reports FOR INSERT TO anon WITH CHECK(true);
-- The event ledger has no UPDATE/DELETE grant; corrections append a new observation.
COMMIT;
